package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.type.TypeFactory;
import com.fasterxml.jackson.databind.util.ArrayBuilders;
import com.fasterxml.jackson.databind.util.ClassUtil;
import com.fasterxml.jackson.databind.util.LRUMap;
import java.io.*;
import java.lang.reflect.*;
import java.math.*;
import java.util.*;
import java.util.Map;
import java.util.Properties;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

/**
 * Unit tests for TypeFactory._fromClass.
 * Since _fromClass is protected, we use a Testable subclass to access it.
 */
public class TypeFactory__fromClass_TriageGen2Test {

    private TestableTypeFactory typeFactory;

    // Subclass to expose protected method for testing
    private static class TestableTypeFactory extends TypeFactory {
        protected TestableTypeFactory() {
            super(null, null);
        }

        @Override
        public JavaType _fromClass(ClassStack context, Class<?> rawType, TypeBindings bindings) {
            return super._fromClass(context, rawType, bindings);
        }
    }

    @Before
    public void setUp() {
        typeFactory = new TestableTypeFactory();
    }

    @Test
    public void test_fromClass_WellKnownSimple() {
        // String is a well-known simple type
        JavaType result = typeFactory._fromClass(null, String.class, null);
        assertNotNull(result);
        assertEquals(String.class, result.getRawClass());
    }

    @Test
    public void test_fromClass_CacheHit() {
        // First call to populate cache
        JavaType first = typeFactory._fromClass(null, Integer.class, null);
        // Second call should hit cache
        JavaType second = typeFactory._fromClass(null, Integer.class, null);

        assertSame("Should return same instance from cache", first, second);
    }

    @Test
    public void test_fromClass_WithBindings_NoCache() {
        // Using bindings makes it non-cachable in the current logic (cachable = bindings == null || bindings.isEmpty())
        TypeBindings bindings = TypeBindings.empty(); 
        // Note: In actual Jackson, bindings is an object. If bindings is not null and not empty, cache is skipped.
        // Since we can't easily construct complex bindings without more context, we test the logic flow.

        JavaType result = typeFactory._fromClass(null, Integer.class, bindings);
        assertNotNull(result);
    }

    @Test
    public void test_fromClass_RecursiveReference() {
        // Create a circular dependency scenario
        // ClassStack context contains the rawType already
        ClassStack context = new ClassStack(String.class); 
        // If we try to resolve String again within its own context, it triggers the self-reference logic

        JavaType result = typeFactory._fromClass(context, String.class, null);

        // According to code: if context.find(rawType) != null -> returns ResolvedRecursiveType
        assertTrue(result instanceof ResolvedRecursiveType);
    }

    @Test
    public void test_fromClass_ArrayType() {
        // Test array logic: rawType.isArray()
        JavaType result = typeFactory._fromClass(null, String[].class, null);

        assertNotNull(result);
        assertTrue(result instanceof ArrayType);
        assertEquals(String.class, ((ArrayType) result).getElementType().getRawClass());
    }

    @Test
    public void test_fromClass_PropertiesSpecialCase() {
        // The code has a specific hardcoded fix for java.util.Properties
        JavaType result = typeFactory._fromClass(null, Properties.class, null);

        assertNotNull(result);
        assertTrue(result instanceof MapType);
        // Properties is treated as Map<String, String>
        assertEquals(String.class, ((MapType) result).getKeyType().getRawClass());
        assertEquals(String.class, ((MapType) result).getValueType().getRawClass());
    }

    @Test
    public void test_fromClass_Interface() {
        // Test path where rawType.isInterface() is true
        JavaType result = typeFactory._fromClass(null, java.util.List.class, null);
        assertNotNull(result);
    }

    @Test
    public void test_fromClass_Enum() {
        // Enums are not interfaces, so they follow the else branch (superClass != null)
        JavaType result = typeFactory._fromClass(null, java.util.concurrent.TimeUnit.class, null);
        assertNotNull(result);
    }

    @Test
    public void test_fromClass_UnknownTypeFallback() {
        // Testing the fallback to _newSimpleType via a custom class if all else fails
        // Using a class that isn't "well known"
        class DummyClass {}
        JavaType result = typeFactory._fromClass(null, DummyClass.class, null);

        assertNotNull(result);
        assertEquals(DummyClass.class, result.getRawClass());
    }

    @Test
    public void test_fromClass_ContextCreation() {
        // If context is null, it should create a new ClassStack
        // We verify this indirectly by ensuring the method completes without NPE
        JavaType result = typeFactory._fromClass(null, Integer.class, null);
        assertNotNull(result);
    }
}
